function claim(id,statement,refs,category="evaluation",limitation="",certainty="moderate"){
 claims.push({...draft,id:cid(id),statement,sourceIds:refs.map(sid),evidenceCategory:category,certainty,
  limitation,applicablePopulation:"The identified synthetic adult clinical or employee teaching cases; observed values are constructed case inputs, not empirical patient/gameplay data.",lastCheckedOn:"2026-11-02"});
}
claim("flumazenil-seizure-control-contraindication","Flumazenil is contraindicated when a benzodiazepine was required to control a potentially life-threatening seizure state.",["flumazenil2025"],"safety_boundary","One adequate primary label. The raw seizure-course application requires anesthesia/neurology review; no duration cutoff or antidote dose is authored.");
claim("midazolam-route-and-monitoring","Boosted protease inhibitors can increase parenteral midazolam exposure, requiring individualized monitored use.",["nysdoh"],"safety_boundary","Retained verified government guidance; no dose, washout, automatic reversal instruction or duration inferred.");
claim("hrm-incomplete-placement","An esophageal pressure study without adequate junction-crossing acquisition cannot establish reliable junction relaxation classification.",["acg-physiology2020","chicago"],"evaluation","Assisted completion is a case-specific application. Persistent failure despite assisted placement may justify complementary FLIP; the cases do not assert manometry must always be repeated.");
claim("hrm-protocol-and-provocation","Adequate separated-swallow protocols and selected provocative maneuvers help determine whether manometry addresses the patient's obstructive symptoms.",["acg-physiology2020","chicago"],"evaluation","The technical protocol and symptom challenge need specialist review; no new quantitative threshold, fluid volume or meal recipe is authored.");
claim("groin-imaging-after-negative-study","Persistent groin diagnostic uncertainty after ultrasound can warrant dynamic cross-sectional imaging, especially with a competing musculoskeletal explanation.",["hernia2018","hernia2023"],"evaluation","Repeat targeted ultrasound for an untested site/provocation is an authored technical application, not a new universal guideline hierarchy. No accuracy rate is claimed.");
claim("groin-symptom-attribution","A painless reducible inguinal hernia in a man may be observed while symptoms from another site receive separate evaluation.",["hernia2018","hernia2023"],"management","Case localization/provocation is synthetic and must be clinically reviewed; neither positive imaging nor a repair consultation guarantees resolution of separate pain.");
claim("thyroid-cystic-node-discordance","Suspicious cervical-node imaging can require targeted FNA and selected thyroglobulin washout despite a nondiagnostic cystic-fluid aspirate.",["ata2025"],"evaluation","Single adequate current primary guideline; washout interpretation with an intact thyroid has limitations. The fictional 12-mm short axis is an observation above the documented sampling criterion, not an invented criterion.");
claim("melanoma-incomplete-biopsy-completion","A partial skin specimen may not establish the diagnosis or maximum invasive depth of an unsampled residual lesion.",["esmo-melanoma2025"],"evaluation","One directly retrieved current guideline supports full-thickness complete diagnostic sampling and maximum-depth/edge reporting. Exact completion technique and sequencing after a specific partial specimen remain clinical inference pending specialist review; completion is not universal when the initial specimen already suffices for planning.");
claim("melanoma-suspicious-node-pathway","Sentinel-node assessment of occult melanoma does not replace evaluation of a proven-positive or unresolved suspicious regional node.",["esmo-melanoma2025","nci-melanoma"],"evaluation","Core targeting after a blood-only miss is an authored specimen-adequacy application, not a quantified accuracy claim; no particular systemic regimen or automatic dissection is asserted.");
claim("colon-indeterminate-liver-mri","Dedicated contrast MRI can characterize a subcentimeter liver lesion left indeterminate by single-phase CT in a patient with extrahepatic cancer.",["acr-liver2020"],"evaluation","Single adequate directly retrieved criteria document. Multiphase CT is also valid but is not offered as wrong; PET is not ruled out universally for larger lesions. The 8-mm focus is fictional.");
claim("colon-adequate-regions-and-chest-ct","Adequate abdominopelvic staging does not replace diagnostic whole-chest assessment for colon cancer.",["ascrs2022"],"evaluation","Retained same-day verified primary coverage rule; current direct access failed. Partial cardiac CT, small nodule and use of the accepted MRI alternative are constructed applications; no nodule follow-up cutoff is invented.");
claim("sarcoma-mri-coverage-and-target","Local MRI for suspected soft-tissue malignancy should depict the full lesion and relevant compartment relationships before biopsy planning.",["essr2023"],"evaluation","Previously verified primary society guidance. Missing enhancement/viability information is a separate target-planning application, requiring radiologist review; no contrast dose or imaging diagnosis is inferred.");
claim("classic-lipoma-normal-mucosal-sample","A characteristic submucosal lipoma need not receive another specimen solely because overlying mucosal tissue is normal.",["sel2022"],"evaluation","One complete primary guideline rechecked for wall layers, diagnostic lipoma patterns and selective tissue acquisition. The normal-mucosa scenario is an anatomic application; atypical or genuinely indeterminate lesions require another pathway.");
claim("gastric-clonality-classification-boundary","Gastric B-cell clonality alone cannot establish a specific lymphoma without integrated morphology and clinical correlation.",["bsh2024","malt-review2023"],"evaluation","Neither preserved glands nor a clonal result independently resolves every case. No unique ranking of repeat endoscopy versus fusion testing is claimed.");
claim("gastric-large-cell-transformation-boundary","Individual larger B cells do not by themselves establish the confluent large-cell component of transformed marginal-zone lymphoma.",["bsh2024"],"evaluation","One adequate primary guideline; a hematopathologist must verify the actual architecture. No Ki-67 cutoff or treatment regimen is authored.");
claim("gastric-eradication-response-pathway","Localized H. pylori-associated indolent gastric MALT lymphoma is generally managed initially with eradication and histologic response assessment.",["bsh2024","malt-review2023"],"management","Not an eradication-only rule for every aggressive component or disease extent. No antibiotic selection or dose added.");
claim("hpylori-test-conditions","The BSH gastric-MALT pathway specifies infection reassessment at least six weeks after therapy starts and two weeks after stopping PPI.",["bsh2024"],"evaluation","Exact timing directly supported by that guideline; this is a clinical-history condition, not a game wait duration or a new universal cancer-response deadline.");
claim("gastric-regressing-residual-monitoring","Asymptomatic residual gastric MALT without adverse progression can be actively monitored after eradication.",["bsh2024","malt-review2023"],"management","The exact clinical/endoscopic/histologic response and follow-up schedule need hematology review; elapsed time alone does not decide failure.");
claim("gastric-molecular-persistence","Persistent molecular clonality after eradication does not by itself require additional gastric lymphoma treatment.",["bsh2024","malt-review2023"],"management","Interpret alongside symptoms, morphology and extent; not a rule to ignore overt progression.");
claim("gastric-negative-fusion-not-exclusion","Absence of BIRC3-MALT1 does not exclude otherwise supported gastric MALT lymphoma.",["bsh2024","malt-review2023"],"evaluation","The molecular finding is not universal and absence does not guarantee eradication response or exclude every mimic.");
claim("gastric-progressive-local-escalation","Symptomatic or overtly progressive localized gastric MALT after eradication warrants consideration of involved-site radiotherapy.",["bsh2024","malt-review2023"],"management","Discussion requires reassessment of extent and histology; no radiation dose, precise failure deadline or automatic treatment is authored.");
claim("uncertain-target-benefit-not-excluded","A nonsignificant result can remain compatible with a worthwhile target effect when its interval includes that effect.",["nist-p","nist-ci"],"definition","Constructed study/protocol only; neither target benefit nor equivalence follows from a p-value alone. No real adoption threshold.");
claim("pancreatic-arterial-focus-before-drainage","A suspected arterial bleeding source associated with a pancreatic collection requires vascular assessment and control before routine collection drainage.",["ksge2021","ilatam2026"],"management","Synthetic enhancement/channel and blood-loss findings need IR review. Resuscitation, individual vascular technique and rescue surgery remain clinical decisions; no new hemodynamic cutoff.");
claim("pancreatic-mri-contents","MRI can better define nonliquid collection contents that remain uncertain on CT before intervention planning.",["ksge2021","ilatam2026"],"evaluation","Not a claim MRI is mandatory after every CT or that all fluid-sensitive brightness is viable tissue.");
claim("pancreatic-necrosis-step-up","A drainage-first step-up strategy can precede necrosectomy for an appropriately selected symptomatic walled-off necrotic collection.",["ksge2021","ilatam2026"],"management","Extent, access, infection and response determine intervention. No universal mandate to debride every solid fragment or fixed maturation interval.");
claim("pancreatic-duct-mapping","MRCP can assess suspected pancreatic duct disruption or disconnection before selecting a drainage strategy.",["ksge2021","ilatam2026"],"evaluation","Current guidance includes low-quality evidence; secretin is preferable when available but is not silently made a required resource in these cases.","low");
claim("pancreatic-partial-leak-bridge","A selected small communicating collection with a partial pancreatic duct leak may be treated by transpapillary bridging when transmural access is unsuitable.",["ksge2021"],"management","One adequate retrieved technical guideline: it describes a small collection under 5 cm and partial rather than complete disruption. The 4-cm case is fictional, not a new cutoff. Exact bridging feasibility requires endoscopy review.","low");
claim("pancreatic-disconnected-long-term-drainage","Symptomatic recurrent collections associated with a disconnected viable upstream gland may require sustained transluminal plastic-stent drainage.",["ilatam2026","ksge2021"],"management","Current recommendation rests on low-quality evidence. No universal stent duration, cure guarantee or ban on later surgery; assess anatomy and individual response.","low");
claim("pdsa-source-specific-next-test","A small improvement test can compare a source-specific adaptation while retaining checks and measuring both burden and record agreement.",["ahrq-pdsa","ahrq-measures"],"definition","Current/prior/dispensing records and times are fictional local inputs. No empirical prefill benefit or patient/question analytics is claimed.");
claim("breast-core-target-discordance","Benign breast tissue that does not explain the suspicious imaging target warrants further representative histologic assessment.",["breast-eusobi2020","asbrs2024-archived"],"evaluation","Repeat core, vacuum-assisted or surgical sampling may be appropriate. The missed-target case does not rank all possible techniques universally; skin sampling alone does not clear an unsampled parenchymal lesion.");
claim("ulcer-rebleeding-repeat-endoscopy","Recurrent peptic-ulcer bleeding after initial successful hemostasis can warrant repeat endoscopic therapy, with consideration of an OTS clip.",["esge-ulcer2026"],"management","One adequate current full primary guideline. Actual resuscitation/access and prior course matter; not a universal requirement to repeat endoscopy despite any instability or contraindication.");
claim("ulcer-failed-repeat-embolization","Transcatheter embolization should be considered after unsuccessful repeat endoscopic hemostasis when available.",["esge-ulcer2026"],"management","One adequate current primary guideline. Surgery may be needed when embolization is unavailable/unsuccessful or individual circumstances require it; no universal vital-sign threshold.");

claim("sarcoma-enhancement-biopsy-target","Contrast-enhanced MRI can help identify viable regions within a soft-tissue mass for representative biopsy targeting.",["essr2023"],"evaluation","Single adequate directly retrieved current primary society consensus; the exact sequence and individual target require MSK review. No contrast dose, signal cutoff or automatic benign/malignant classification is inferred.");

claim("groin-inadequate-study-certainty","An outside study that did not assess the clinical groin site or provoking event can leave the hernia diagnosis unresolved.",["hernia2018","hernia2023"],"evaluation","Diagnostic-concordance application of targeted assessment guidance, not a measured sensitivity claim or a universal rule against photographic diagnosis. The actual photograph and acquisition need clinical review; dynamic MRI is not asserted inferior to adequate ultrasound.");

claim("qi-comparison-input-control","Keeping the clinical input source constant helps distinguish an entry-method change from a simultaneous record-source change in a process comparison.",["nist-comparison","ahrq-pdsa","ahrq-measures"],"definition","Original application of experimental-control guidance to a constructed local PDSA comparison. Not a universal one-factor-at-a-time requirement, randomized-trial claim, guarantee of software benefit or clinical recommendation.");

